    const T* Kb = Kg + (size_t)bh * (size_t)SEQ * (size_t)D;
    const T* Vb = Vg + (size_t)bh * (size_t)SEQ * (size_t)D;
    T*       Ob = Og + (size_t)bh * (size_t)SEQ * (size_t)D;

    // Global tensors described with CuTe (row-major: D contiguous)
