cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <math.h>
#include <cuda_fp16.h>
#include <mma.h>

using namespace cute;

// Fused attention kernel:
//   S = scale * Q @ K^T   (contract over head-dim D)
//   P = softmax_row(S)    (over full key dimension SEQ)
//   O = P @ V             (contract over key dimension SEQ, produce D outputs)
//
// One block handles a tile of BLOCK_M query rows for one (batch,head) pair.
// The full key/value sequence (SEQ) is kept resident logically (S/P buffer in
// shared memory), while the head-dimension D is streamed in DK/DV sized
// chunks through shared memory to bound shared-memory usage.
template <typename T, int BLOCK_M, int DK, int DV, int THREADS>
__global__ void fused_attention_kernel(
    const T* __restrict__ Qg,
    const T* __restrict__ Kg,
    const T* __restrict__ Vg,
    T* __restrict__ Og,
    int BH, int SEQ, int D, float scale)
{
    int bh     = blockIdx.y;
    int m_tile = blockIdx.x;
    int m0     = m_tile * BLOCK_M;
    int m_count = min(BLOCK_M, SEQ - m0);
    if (m_count <= 0) return;

    const T* Qb = Qg + (size_t)bh * (size_t)SEQ * (size_t)D;
    const T* Kb = Kg + (size_t)bh * (size_t)SEQ * (size_t)D;
    const T* Vb = Vg + (size_t)bh * (size_t)SEQ * (size_t)D;
    T*       Ob = Og + (size_t)bh * (size_t)SEQ * (size_t)D;

    // Global tensors described with CuTe (row-major: D contiguous)
    auto gQ = make_tensor(make_gmem_ptr(Qb), make_shape(SEQ, D), make_stride(D, 1));
    auto gK = make_tensor(make_gmem_ptr(Kb), make_shape(SEQ, D), make_stride(D, 1));
    auto gV = make_tensor(make_gmem_ptr(Vb), make_shape(SEQ, D), make_stride(D, 1));
    auto gO = make_tensor(make_gmem_ptr(Ob), make_shape(SEQ, D), make_stride(D, 1));

    extern __shared__ unsigned char smem_raw[];

    size_t qk_bytes   = (size_t)BLOCK_M * DK * sizeof(T) + (size_t)SEQ * DK * sizeof(T);
    size_t v_bytes    = (size_t)SEQ * DV * sizeof(T);
    size_t swap_bytes = qk_bytes > v_bytes ? qk_bytes : v_bytes;
    swap_bytes = (swap_bytes + 7) & ~size_t(7);

    T*     Q_tile_ptr = reinterpret_cast<T*>(smem_raw);
    T*     K_tile_ptr = Q_tile_ptr + BLOCK_M * DK;
    float* S_ptr      = reinterpret_cast<float*>(smem_raw + swap_bytes);

    auto sQ = make_tensor(make_smem_ptr(Q_tile_ptr), make_shape(BLOCK_M, DK), make_stride(DK, 1));
    auto sK = make_tensor(make_smem_ptr(K_tile_ptr), make_shape(SEQ, DK), make_stride(DK, 1));
    auto sS = make_tensor(make_smem_ptr(S_ptr), make_shape(BLOCK_M, SEQ), make_stride(SEQ, 1));
    size_t s_bytes_ = (size_t)BLOCK_M * SEQ * sizeof(float);
    size_t p_bytes_ = (size_t)BLOCK_M * SEQ * sizeof(T);
    p_bytes_ = (p_bytes_ + 7) & ~size_t(7);
    T*     P_half_ptr = reinterpret_cast<T*>(smem_raw + swap_bytes + s_bytes_);
    float* O_tmp_ptr  = reinterpret_cast<float*>(smem_raw + swap_bytes + s_bytes_ + p_bytes_);
    auto sP     = make_tensor(make_smem_ptr(P_half_ptr), make_shape(BLOCK_M, SEQ), make_stride(SEQ, 1));
    auto sO_tmp = make_tensor(make_smem_ptr(O_tmp_ptr), make_shape(BLOCK_M, DV), make_stride(DV, 1));

    int tid = threadIdx.x;

    // zero S accumulator
    for (int e = tid; e < BLOCK_M * SEQ; e += THREADS) {
        int m = e / SEQ, n = e % SEQ;
        sS(m, n) = 0.0f;
    }
    __syncthreads();

    // ---- Phase 1: S = Q @ K^T via Tensor Core WMMA (accumulate raw dot products) ----
    using namespace nvcuda;
    const int NUM_WARPS = THREADS / 32;
    const int N_TILES = SEQ / 16;
    const int MAX_NT_PER_WARP = 4;
    int warp_id = tid / 32;
    int nt_per_warp = (N_TILES + NUM_WARPS - 1) / NUM_WARPS;
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc_frag[MAX_NT_PER_WARP];
    for (int i = 0; i < MAX_NT_PER_WARP; ++i) {
        wmma::fill_fragment(acc_frag[i], 0.0f);
    }
    for (int d0 = 0; d0 < D; d0 += DK) {
        int dk_count = min(DK, D - d0);
        for (int e2 = tid; e2 < BLOCK_M * (DK / 2); e2 += THREADS) {
            int m = e2 / (DK / 2);
            int k2 = e2 % (DK / 2);
            int k = k2 * 2;
            __half2 val2 = __float2half2_rn(0.0f);
            if (m < m_count) {
                if (k + 1 < dk_count) {
                    val2 = *reinterpret_cast<const __half2*>(&gQ(m0 + m, d0 + k));
                } else if (k < dk_count) {
                    __half lo = *reinterpret_cast<const __half*>(&gQ(m0 + m, d0 + k));
                    val2 = __halves2half2(lo, __float2half(0.0f));
                }
            }
            *reinterpret_cast<__half2*>(&sQ(m, k)) = val2;
        }
        for (int e2 = tid; e2 < SEQ * (DK / 2); e2 += THREADS) {
            int n = e2 / (DK / 2);
            int k2 = e2 % (DK / 2);
            int k = k2 * 2;
            __half2 val2 = __float2half2_rn(0.0f);
            if (k + 1 < dk_count) {
                val2 = *reinterpret_cast<const __half2*>(&gK(n, d0 + k));
            } else if (k < dk_count) {
                __half lo = *reinterpret_cast<const __half*>(&gK(n, d0 + k));
                val2 = __halves2half2(lo, __float2half(0.0f));
            }
            *reinterpret_cast<__half2*>(&sK(n, k)) = val2;
        }
        __syncthreads();
        int k_tiles = DK / 16;
        for (int i = 0; i < nt_per_warp; ++i) {
            int nt = warp_id + i * NUM_WARPS;
            if (nt >= N_TILES) continue;
            for (int kt = 0; kt < k_tiles; ++kt) {
                wmma::fragment<wmma::matrix_a, 16, 16, 16, half, wmma::row_major> a_frag;
                wmma::fragment<wmma::matrix_b, 16, 16, 16, half, wmma::col_major> b_frag;
                const half* a_ptr = reinterpret_cast<const half*>(&sQ(0, kt * 16));
                const half* b_ptr = reinterpret_cast<const half*>(&sK(nt * 16, kt * 16));
                wmma::load_matrix_sync(a_frag, a_ptr, DK);
                wmma::load_matrix_sync(b_frag, b_ptr, DK);
                wmma::mma_sync(acc_frag[i], a_frag, b_frag, acc_frag[i]);
            }
        }
        __syncthreads();
    }
    for (int i = 0; i < nt_per_warp; ++i) {
        int nt = warp_id + i * NUM_WARPS;
        if (nt >= N_TILES) continue;
        float* s_ptr = &sS(0, nt * 16);
        wmma::store_matrix_sync(s_ptr, acc_frag[i], SEQ, wmma::mem_row_major);
    }
    __syncthreads();

    // scale
    for (int e = tid; e < BLOCK_M * SEQ; e += THREADS) {
        int m = e / SEQ, n = e % SEQ;
        sS(m, n) = sS(m, n) * scale;
    }
    __syncthreads();

    // ---- Phase 2: row-wise softmax over full key dimension ----
    // Parallelize each row's reduction across a group of GROUP threads
    // (using warp-shuffle sub-warp reductions) instead of a single thread
    // per row looping serially over SEQ -- this uses all THREADS threads
    // concurrently (BLOCK_M groups of THREADS/BLOCK_M threads each) rather
    // than leaving THREADS-BLOCK_M threads idle during softmax.
    {
        constexpr int GROUP = THREADS / BLOCK_M; // threads cooperating per row
        int m = tid / GROUP;
        int lane = tid % GROUP;
        if (m < m_count) {
            float maxv = -INFINITY;
            for (int n = lane; n < SEQ; n += GROUP) {
                maxv = fmaxf(maxv, sS(m, n));
            }
            #pragma unroll
            for (int off = GROUP / 2; off > 0; off >>= 1) {
                maxv = fmaxf(maxv, __shfl_xor_sync(0xffffffff, maxv, off, GROUP));
            }
            float sum = 0.0f;
            for (int n = lane; n < SEQ; n += GROUP) {
                float e = __expf(sS(m, n) - maxv);
                sS(m, n) = e;
                sum += e;
            }
            #pragma unroll
            for (int off = GROUP / 2; off > 0; off >>= 1) {
                sum += __shfl_xor_sync(0xffffffff, sum, off, GROUP);
            }
            float inv = 1.0f / sum;
            for (int n = lane; n < SEQ; n += GROUP) {
                sS(m, n) = sS(m, n) * inv;
            }
        }
    }
    __syncthreads();
    for (int e = tid; e < BLOCK_M * SEQ; e += THREADS) {
        int m = e / SEQ, n = e % SEQ;
        sP(m, n) = T(sS(m, n));
    }
    __syncthreads();

    // ---- Phase 3: O = P @ V via Tensor Core WMMA, streaming V over head dimension ----
    T* V_tile_ptr = reinterpret_cast<T*>(smem_raw);
    auto sV = make_tensor(make_smem_ptr(V_tile_ptr), make_shape(SEQ, DV), make_stride(DV, 1));
    const int N_TILES_V = DV / 16;
    const int K_TILES_V = SEQ / 16;
    const int MAX_NT_PER_WARP_V = 4;
    int nt_per_warp_v = (N_TILES_V + NUM_WARPS - 1) / NUM_WARPS;
    for (int d0 = 0; d0 < D; d0 += DV) {
        int dv_count = min(DV, D - d0);
        for (int e2 = tid; e2 < SEQ * (DV / 2); e2 += THREADS) {
            int n = e2 / (DV / 2);
            int dv2 = e2 % (DV / 2);
            int dv = dv2 * 2;
            __half2 val2 = __float2half2_rn(0.0f);
            if (dv + 1 < dv_count) {
                val2 = *reinterpret_cast<const __half2*>(&gV(n, d0 + dv));
            } else if (dv < dv_count) {
                __half lo = *reinterpret_cast<const __half*>(&gV(n, d0 + dv));
                val2 = __halves2half2(lo, __float2half(0.0f));
            }
            *reinterpret_cast<__half2*>(&sV(n, dv)) = val2;
        }
        __syncthreads();
        wmma::fragment<wmma::accumulator, 16, 16, 16, float> oacc_frag[MAX_NT_PER_WARP_V];
        for (int i = 0; i < nt_per_warp_v; ++i) {
            int nt = warp_id + i * NUM_WARPS;
            if (nt >= N_TILES_V) continue;
            wmma::fill_fragment(oacc_frag[i], 0.0f);
            for (int kt = 0; kt < K_TILES_V; ++kt) {
                wmma::fragment<wmma::matrix_a, 16, 16, 16, half, wmma::row_major> p_frag;
                wmma::fragment<wmma::matrix_b, 16, 16, 16, half, wmma::row_major> v_frag;
                const half* p_ptr = reinterpret_cast<const half*>(&sP(0, kt * 16));
                const half* v_ptr = reinterpret_cast<const half*>(&sV(kt * 16, nt * 16));
                wmma::load_matrix_sync(p_frag, p_ptr, SEQ);
                wmma::load_matrix_sync(v_frag, v_ptr, DV);
                wmma::mma_sync(oacc_frag[i], p_frag, v_frag, oacc_frag[i]);
            }
            float* o_ptr = &sO_tmp(0, nt * 16);
            wmma::store_matrix_sync(o_ptr, oacc_frag[i], DV, wmma::mem_row_major);
        }
        __syncthreads();
        for (int e = tid; e < BLOCK_M * DV; e += THREADS) {
            int m = e / DV;
            int dv = e % DV;
            if (m < m_count && dv < dv_count) {
                gO(m0 + m, d0 + dv) = T(sO_tmp(m, dv));
            }
        }
        __syncthreads();
    }
}

